 if (select meta->>'production_revision' from public.marketing_calendar_plans where id='noviembre-2026')='two-shoots-v2' then return; end if;
 perform 1 from public.marketing_calendar_plans where id='noviembre-2026' for update;
 if not exists(select 1 from public.marketing_calendar_plans where id='noviembre-2026' and meta='{"end": "2026-12-06", "scope": "4 reels + 15 posts de feed. 34 secuencias de stories del 3/11 al 6/12, adicionales al paquete. Fechas y horas propuestas; no es un programador de Instagram.", "start": "2026-11-01", "title": "Calendario comercial · noviembre 2026", "edition": "2026-11-03", "sources": [{"url": "https://about.fb.com/news/2024/10/best-practices-education-hub-creators-instagram/", "title": "Meta · Best Practices de Instagram", "finding": "Meta organiza recomendaciones de creación, interacción y alcance y ofrece consejos personalizados en el panel profesional. Sustenta revisar Insights propios, sin afirmar una hora universal."}, {"url": "https://about.fb.com/news/2024/12/trial-reels-try-content-non-followers-first-see-what-perfoms-best/", "title": "Meta · Trial Reels", "finding": "Meta describe pruebas con no seguidores para explorar formatos. Si la función aparece en la cuenta, usarla en R01 o R03; mantener R02 y R04 en el calendario normal por su vigencia. No añadir reels fuera del paquete."}, {"url": "https://about.fb.com/news/2025/06/inspiring-creativity-that-brings-people-together/", "title": "Meta · Creatividad y pruebas", "finding": "Apoya experimentar con contenido y observar la respuesta. Los formatos y guiones propuestos aquí son una inferencia creativa para Importados, no un estudio de ventas de esta cuenta."}, {"url": "https://www.instagram.com/tiendasimportados/", "title": "Instagram de Importados · revisión manual pendiente", "finding": "Fuente propia a contrastar por el equipo; no se pudo auditar el feed actual desde esta sesión."}], "strategy": [{"body": "R01: recorrido POV para descubrimiento local. R02: presentador y tres motivos para asistir. R03: transformación antes/después para mostrar utilidad. R04: lista navideña y oferta para consulta o visita. Son hipótesis de producción para esta tienda, no formatos con viralidad garantizada.", "title": "Cuatro reels, cuatro trabajos"}, {"body": "Natillada y ubicación generan confianza; invitación y cobertura llevan a la inauguración; memoria del evento valida la experiencia; guías y lista preparan Black Friday; diciembre vuelve a inspiración sin prolongar el 20 %.", "title": "Una campaña que acumula intención"}, {"body": "Cuatro mañanas de rodaje propuestas, una por reel. Grabar video vertical propio 9:16, voz clara, subtítulos y producto desde el primer plano; revisar zonas cubiertas por la interfaz antes de exportar. Feed 4:5 y carruseles de 4–6 láminas; portada con una idea, cierre con una acción. Usar audio con derechos de uso comercial.", "title": "Grabación que se puede ejecutar"}, {"body": "Feed entre semana 18:30; sábado de lista/selección 11:30; anuncios de inicio 08:30/09:00. Stories en tres ventanas, con cobertura extra en eventos. America/Bogota. Ajustar con Insights propios tras dos semanas: no tenemos métricas actuales de la cuenta.", "title": "Horario de partida, no «mejor hora» probada"}, {"body": "A las 24 h y 7 días: alcance, tiempo medio de reproducción y retención si están disponibles, compartidos/alcance, guardados/alcance, visitas al perfil y seguidores netos. Registrar consultas cualificadas por pieza (producto + sede + intención), visitas autodeclaradas y ventas verificadas por separado. No confundir reproducción, clic o consulta con venta.", "title": "Medición útil para retail"}, {"body": "Sin gasto ni publicación automática desde este módulo. Propuesta: promover R02 para asistencia local antes del 14; R04 para consultas navideñas del 27 al 29. Separar Niquía de Santa Lucía y revisar radio real por desplazamiento; no fraccionar un presupuesto pequeño en muchos conjuntos. Escalar por consulta cualificada y compra verificable, no por seguidores baratos; presupuesto y anuncios requieren decisión posterior.", "title": "Pauta después de validar la pieza"}, {"body": "Las ocho fotos aportadas son referencias de licuadora, arrocera, trenes, Papá Noel, detalles dorados/plateados y árboles. Las etiquetas fotografiadas no son autorización para anunciar precios ni aplicarles otro descuento. Solicitar un inventario visual adicional de Navidad; mostrar luces, bolas, guirnaldas o empaques solo si se confirma que se venden.", "title": "Productos reales, no catálogo cerrado"}, {"body": "Se intentó revisar el perfil público y su embed el 3/11/2026: Instagram bloqueó la lectura automatizada y la búsqueda no recuperó publicaciones verificables. No se atribuyen métricas, frecuencia ni piezas recientes a la cuenta. El material previamente compartido muestra fachada, presentadora y estética amarilla/negra; se mantiene esa continuidad. Antes de producir, el equipo debe contrastar los 19 temas con el feed real y evitar duplicados.", "title": "Revisión de Instagram: alcance y límite"}, {"body": "Inauguración: 20 % en casi toda la tienda, sin transformarlo en «toda». Black Friday: 20 % en toda la tienda 27–29, pendiente de condiciones finales. Rifa: compra y seguir Instagram confirmados; faltan bases. Concurso: dos componentes de $500.000, sin sumar como efectivo. Artista: imitadora de Arelys Henao, sin aparentar contratación de la cantante original. Horarios de shows sin definir.", "title": "Promociones con información clara"}], "timezone": "America/Bogota"}'::jsonb) then raise exception 'Calendar strategy changed; review before updating'; end if;
 perform 1 from public.marketing_calendar_items where id='S1103' and plan_id='noviembre-2026' and revision=1 and data='{"id": "S1103", "date": "2026-11-03", "kind": "story", "time": "10:30", "title": "Tu Navidad empieza a tomar forma", "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "format": "Secuencia · 3 stories · 1080 × 1920", "script": [], "season": "niquia", "status": "planned", "caption": "10:30 · Foto de producto real: «¿Ya empezaste a pensar en Navidad?»\n13:00 · Encuesta: «¿Árbol primero o detalles primero?»\n18:30 · Fachada + dirección Niquía y enlace a ubicación.", "outline": ["10:30 · Foto de producto real: «¿Ya empezaste a pensar en Navidad?»", "13:00 · Encuesta: «¿Árbol primero o detalles primero?»", "18:30 · Fachada + dirección Niquía y enlace a ubicación."], "end_date": "2026-11-03", "revision": 1, "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al paquete de 4 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra."}'::jsonb for update;
 if not found then raise exception 'Calendar item changed: S1103'; end if;
