 perform 1 from public.marketing_calendar_items where id='S1105' and plan_id='noviembre-2026' and revision=1 and data='{"id": "S1105", "date": "2026-11-05", "kind": "story", "time": "10:30", "title": "Stories: POV: entras por una cosa en Niquía", "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "format": "Secuencia · 3 stories · 1080 × 1920", "script": [], "season": "niquia", "status": "planned", "caption": "10:30 · Video propio de tren navideño; mostrar uso o detalle real, sin afirmar funciones no probadas.\n13:00 · Recompartir R01 con una pregunta relacionada.\n18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias.", "outline": ["10:30 · Video propio de tren navideño; mostrar uso o detalle real, sin afirmar funciones no probadas.", "13:00 · Recompartir R01 con una pregunta relacionada.", "18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias."], "end_date": "2026-11-05", "revision": 1, "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al paquete de 4 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra."}'::jsonb for update;
