 perform 1 from public.marketing_calendar_items where id='R01' and plan_id='noviembre-2026' and revision=1 and data='{"id": "R01", "date": "2026-11-05", "kind": "reel", "time": "18:30", "title": "POV: entras por una cosa en Niquía", "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/01-licuadora.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación.", "Confirmar permiso de las personas reconocibles; no mostrar menores sin autorización de su responsable."], "format": "Reel · 1080 × 1920", "script": [{"text": "POV: entras por una cosa", "time": "0–2 s", "voice": "Vine por una cosita…", "visual": "Mano abre la puerta y toma un producto."}, {"text": "Árbol / detalles / regalos", "time": "2–7 s", "voice": "…y terminé haciendo mi lista de Navidad.", "visual": "Tres cortes: árbol, Papá Noel, detalle de mesa."}, {"text": "Niquía, ya estamos abiertos", "time": "7–13 s", "voice": "En Importados Niquía encuentras ideas para tu casa y para regalar.", "visual": "Presentador muestra hogar y navidad, referencias distintas."}, {"text": "Diagonal 55 Av 38-33 · Valkiria", "time": "13–19 s", "voice": "Estamos en el edificio Valkiria, Diagonal 55 Av 38-33.", "visual": "Fachada completa y dirección legible."}, {"text": "Envíalo a quien vendría contigo", "time": "19–25 s", "voice": "Ven a conocernos y celebra con nosotros el 14 y 15 de noviembre.", "visual": "Presentador señala cartel con fechas."}], "season": "niquia", "status": "planned", "caption": "POV: entras por una cosa… y empiezas a hacer tu lista 💛🖤 Ya estamos abiertos en Niquía: Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nNos visitas de 9:00 a. m. a 8:00 p. m. Y el 14 y 15 de noviembre celebramos la gran inauguración.\n¿Con quién vendrías? Envíale este recorrido.\n#Niquía #Bello #TiendasImportados", "outline": ["Duración objetivo 22–25 s. Grabar el recorrido real, no una sucesión de pósteres.", "Primera imagen con persona entrando y producto visible, sin introducción de logo.", "Subtítulos, sonido propio/uso comercial autorizado y una sola llamada a compartir."], "end_date": "2026-11-05", "revision": 1, "objective": "Descubrimiento local: mostrar recorrido y variedad con una situación reconocible.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Grabar 4/11 por la mañana. Gancho alternativo sobre el mismo montaje: «Niquía: mira lo que encontramos en Valkiria». No cuenta como un quinto reel."}'::jsonb for update;
