 perform 1 from public.marketing_calendar_items where id='P03' and plan_id='noviembre-2026' and revision=1 and data='{"id": "P03", "date": "2026-11-08", "kind": "post", "time": "18:30", "title": "¿Tu Navidad es dorada o plateada?", "assets": ["/marketing-assets/05-decoracion-dorada.jpeg", "/marketing-assets/06-decoracion-plateada.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/08-arboles.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "format": "Carrusel · 1080 × 1350", "script": [], "season": "navidad", "status": "planned", "caption": "¿Team dorado o team plateado? ✨ Los detalles cambian el ambiente de tu casa. Desliza, elige tu estilo y guarda tus favoritos para empezar a preparar Navidad.\nCuéntanos tu elección y te ayudamos a consultar las referencias disponibles. 💛🖤\n#NavidadEnCasa #TiendasImportados #DecoraciónNavideña", "outline": ["Portada con contraste de piezas doradas y plateadas.", "Foto dorada en un ambiente real, no solo estantería.", "Foto plateada en el mismo encuadre.", "Composición con figura navideña y árbol; referencias por confirmar.", "Cierre: «Guarda tu estilo. ¿Dorado o plateado?»"], "end_date": "2026-11-08", "revision": 1, "objective": "Conseguir guardados y preferencias para preparar la selección de Black Friday.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Usar las fotos recibidas como referencias; producir composiciones nuevas, sin atribuir material o función no confirmados."}'::jsonb for update;
