 update public.marketing_calendar_items set data='{"id": "S1103", "date": "2026-11-03", "time": "10:30", "end_date": "2026-11-03", "kind": "story", "season": "niquia", "title": "Tu Navidad empieza a tomar forma", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · Foto de producto real: «¿Ya empezaste a pensar en Navidad?»\n13:00 · Encuesta: «¿Árbol primero o detalles primero?»\n18:30 · Fachada + dirección Niquía y enlace a ubicación.", "outline": ["10:30 · Foto de producto real: «¿Ya empezaste a pensar en Navidad?»", "13:00 · Encuesta: «¿Árbol primero o detalles primero?»", "18:30 · Fachada + dirección Niquía y enlace a ubicación."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al plan de 5 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra. Usar recursos de los rodajes 5/11 y 19/11 (segundo propuesto). La actualidad del evento solo se muestra si tienda aporta material espontáneo real; no se programa un rodaje adicional.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1103' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1104", "date": "2026-11-04", "time": "10:30", "end_date": "2026-11-04", "kind": "story", "season": "niquia", "title": "Revivimos la natillada", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · Foto real del 1/11 + «Así compartimos la natillada».\n13:00 · Recompartir P01 con «¿Estuviste?»\n18:30 · Caja: «¿Qué te gustaría que hagamos en la próxima actividad?»", "outline": ["10:30 · Foto real del 1/11 + «Así compartimos la natillada».", "13:00 · Recompartir P01 con «¿Estuviste?»", "18:30 · Caja: «¿Qué te gustaría que hagamos en la próxima actividad?»"], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al plan de 5 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra. Usar recursos de los rodajes 5/11 y 19/11 (segundo propuesto). La actualidad del evento solo se muestra si tienda aporta material espontáneo real; no se programa un rodaje adicional.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1104' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "A01", "date": "2026-11-05", "time": "09:00", "end_date": "2026-11-05", "kind": "activity", "season": "niquia", "title": "Rodaje 1 · inauguración + banco de contenido", "objective": "Grabar R01, R02 y R05, fotografías y banco reutilizable de la primera mitad del mes.", "caption": "", "outline": ["09:00–09:30 · Preparar fachada, tienda, presentador, audio, referencias de productos y permisos. Horario completo propuesto: 09:00–14:00.", "09:30–10:15 · R01: recorrido POV y ubicación; grabar primero para poder editar y publicar el mismo día a las 18:30.", "10:15–11:00 · R02: invitación orgánica de tres motivos; grabar cada razón por separado.", "11:00–12:15 · R05: anuncio de inauguración con descuento, rifa, artistas y concurso. Grabar tomas modulares para cambiar datos sin otra visita.", "12:15–13:00 · Fotos verticales y horizontales de fachada, equipo, premios reales si están disponibles y referencias navideñas; alimentar P02–P07 y P09 con el banco/fotos ya recibidas.", "13:00–14:00 · Recursos de pasillos, manos, detalles, interacción y cierre; locuciones alternativas sin horarios de shows ni modelos aún no confirmados.", "Entrega: R01 corte el 5 a las 16:00 y aprobación antes de las 18:30; R05 montaje 6/11, revisión 7/11 y cierre 8/11 para publicar el 9; R02 revisión antes del 10/11."], "assets": [], "checks": ["Confirmar permiso de las personas reconocibles; no mostrar menores sin autorización de su responsable."], "script": [], "format": "Rodaje 1 de 2 · jueves 5 confirmado / horario propuesto", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Primer rodaje confirmado por Samuel para el jueves 5. Hora 09:00–14:00 propuesta. Reunir condiciones de promociones, bases de premios y artes autorizados antes del rodaje; los datos faltantes se completan con sobreimpresos y locución, sin tercera jornada. El material retrospectivo de natillada/inauguración depende de fotos existentes o espontáneas de tienda; si faltan, usar piezas gráficas sin simular el evento.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='A01' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1105", "date": "2026-11-05", "time": "10:30", "end_date": "2026-11-05", "kind": "story", "season": "niquia", "title": "Stories: POV: entras por una cosa en Niquía", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · Video propio de tren navideño; mostrar uso o detalle real, sin afirmar funciones no probadas.\n13:00 · Recompartir R01 con una pregunta relacionada.\n18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias.", "outline": ["10:30 · Video propio de tren navideño; mostrar uso o detalle real, sin afirmar funciones no probadas.", "13:00 · Recompartir R01 con una pregunta relacionada.", "18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al plan de 5 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra. Usar recursos de los rodajes 5/11 y 19/11 (segundo propuesto). La actualidad del evento solo se muestra si tienda aporta material espontáneo real; no se programa un rodaje adicional.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1105' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "R01", "date": "2026-11-05", "time": "18:30", "end_date": "2026-11-05", "kind": "reel", "season": "niquia", "title": "POV: entras por una cosa en Niquía", "objective": "Descubrimiento local: mostrar recorrido y variedad con una situación reconocible.", "caption": "POV: entras por una cosa… y empiezas a hacer tu lista 💛🖤 Ya estamos abiertos en Niquía: Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nNos visitas de 9:00 a. m. a 8:00 p. m. Y el 14 y 15 de noviembre celebramos la gran inauguración.\n¿Con quién vendrías? Envíale este recorrido.\n#Niquía #Bello #TiendasImportados", "outline": ["Duración objetivo 22–25 s. Grabar el recorrido real, no una sucesión de pósteres.", "Primera imagen con persona entrando y producto visible, sin introducción de logo.", "Subtítulos, sonido propio/uso comercial autorizado y una sola llamada a compartir."], "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/01-licuadora.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación.", "Confirmar permiso de las personas reconocibles; no mostrar menores sin autorización de su responsable."], "script": [{"time": "0–2 s", "visual": "Mano abre la puerta y toma un producto.", "voice": "Vine por una cosita…", "text": "POV: entras por una cosa"}, {"time": "2–7 s", "visual": "Tres cortes: árbol, Papá Noel, detalle de mesa.", "voice": "…y terminé haciendo mi lista de Navidad.", "text": "Árbol / detalles / regalos"}, {"time": "7–13 s", "visual": "Presentador muestra hogar y navidad, referencias distintas.", "voice": "En Importados Niquía encuentras ideas para tu casa y para regalar.", "text": "Niquía, ya estamos abiertos"}, {"time": "13–19 s", "visual": "Fachada completa y dirección legible.", "voice": "Estamos en el edificio Valkiria, Diagonal 55 Av 38-33.", "text": "Diagonal 55 Av 38-33 · Valkiria"}, {"time": "19–25 s", "visual": "Presentador señala cartel con fechas.", "voice": "Ven a conocernos y celebra con nosotros el 14 y 15 de noviembre.", "text": "Envíalo a quien vendría contigo"}], "format": "Reel · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Rodaje 1 · jueves 5/11, primer bloque 09:30–10:15. Edición prioritaria hasta las 16:00 y aprobación antes de las 18:30 para publicación el mismo día. Si se retrasa, reprogramar explícitamente la pieza y su story; no publicarla sin revisión. Gancho alternativo en la misma captura: «Niquía: mira lo que encontramos en Valkiria»; es otra toma del mismo reel.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='R01' and plan_id='noviembre-2026';
