 update public.marketing_calendar_items set data='{"id": "S1111", "date": "2026-11-11", "time": "10:30", "end_date": "2026-11-11", "kind": "story", "season": "niquia", "title": "Plan para el fin de semana", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · «14 y 15: agenda la inauguración».\n13:00 · Recompartir R02 + sticker de cuenta regresiva a apertura de tienda, no a shows sin hora.\n18:30 · Dirección Valkiria + enlace de Maps.", "outline": ["10:30 · «14 y 15: agenda la inauguración».", "13:00 · Recompartir R02 + sticker de cuenta regresiva a apertura de tienda, no a shows sin hora.", "18:30 · Dirección Valkiria + enlace de Maps."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al plan de 5 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra. Usar recursos de los rodajes 5/11 y 19/11 (segundo propuesto). La actualidad del evento solo se muestra si tienda aporta material espontáneo real; no se programa un rodaje adicional.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1111' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "R02", "date": "2026-11-11", "time": "18:30", "end_date": "2026-11-11", "kind": "reel", "season": "niquia", "title": "Tres razones para venir a la inauguración", "objective": "Invitación humana con beneficio y ubicación; premiación solo con bases.", "caption": "¡Niquía, tenemos plan para el 14 y 15 de noviembre! 💛 Música, trova, variedad y 20 % de descuento en gran parte de la tienda.\nNos acompañarán Toto y Sirirí y la imitadora de Arelys Henao de Yo Me Llamo. Consulta la programación y condiciones en nuestras stories.\n📍 Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello. Envíale este plan a quien te acompaña. 🖤", "outline": ["Duración 28–32 s; presentador en fachada + pruebas visuales de tienda.", "Versión principal no depende de publicar bases de rifas.", "Si se aprueban premios, usar stories/P05; no saturar el reel con todas las condiciones."], "assets": [], "checks": ["Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración.", "Confirmar día y hora de cada artista y actividad; presentar a la artista como imitadora de Arelys Henao de Yo Me Llamo, sin sugerir que viene la cantante original.", "Autorización del material promocional de artistas."], "script": [{"time": "0–3 s", "visual": "Presentador frente a fachada, gesto de tres razones.", "voice": "Niquía, te damos tres razones para salir este 14 y 15.", "text": "14 y 15 NOV · Niquía"}, {"time": "3–10 s", "visual": "Cortes de presentador y artes autorizados de artistas.", "voice": "Uno: música en vivo, Toto y Sirirí y la imitadora de Arelys Henao de Yo Me Llamo.", "text": "Música y trova · horarios por anunciar"}, {"time": "10–17 s", "visual": "Pasillos/productos reales, rótulo descuento.", "voice": "Dos: 20 % de descuento en gran parte de la tienda.", "text": "20 % · consulta exclusiones y condiciones"}, {"time": "17–24 s", "visual": "Persona compara dos detalles y sonríe.", "voice": "Tres: descubrir ideas para tu casa y preparar Navidad.", "text": "Ven a conocer la variedad"}, {"time": "24–32 s", "visual": "Fachada, dirección y tarjeta final.", "voice": "Te esperamos en Valkiria, Diagonal 55 Av 38-33. Guarda las fechas y ven acompañado.", "text": "14–15 NOV · comparte este plan"}], "format": "Reel · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Rodaje 1 · jueves 5/11. Edición y revisión antes del 10/11, publicación orgánica el 11. Se mantiene distinto de R05: tres motivos y un mensaje corto; R05 reúne todas las dinámicas para pauta. No usar grabaciones de la cantante original como si se presentara en Importados.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='R02' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1112", "date": "2026-11-12", "time": "10:30", "end_date": "2026-11-12", "kind": "story", "season": "niquia", "title": "Rifa y concurso: solo con bases", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · Premios reales, solo tras aprobar bases.\n13:00 · Compra en tienda + seguir Instagram; enlazar reglas completas.\n18:30 · Concurso: $500.000 efectivo + $500.000 tienda; cupos/edades según bases. Si faltan, reemplazar por recorrido de tienda.", "outline": ["10:30 · Premios reales, solo tras aprobar bases.", "13:00 · Compra en tienda + seguir Instagram; enlazar reglas completas.", "18:30 · Concurso: $500.000 efectivo + $500.000 tienda; cupos/edades según bases. Si faltan, reemplazar por recorrido de tienda."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación.", "Aprobar bases de la rifa: compra mínima si aplica, fechas, comprobante, número de participaciones, requisitos, fecha/método del sorteo, entrega, modelos/cantidades de premios y revisión de requisitos aplicables. Compra + seguir Instagram es la única mecánica confirmada.", "Aprobar bases, edades, dinámica y seguridad del concurso «Culi chupado», cupos y entrega de premios: $500.000 en efectivo + $500.000 para gastar en tienda. No prometer $1.000.000 en efectivo."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al plan de 5 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra. Usar recursos de los rodajes 5/11 y 19/11 (segundo propuesto). La actualidad del evento solo se muestra si tienda aporta material espontáneo real; no se programa un rodaje adicional.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1112' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1113", "date": "2026-11-13", "time": "10:30", "end_date": "2026-11-13", "kind": "story", "season": "niquia", "title": "Mañana celebramos", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · «Mañana empieza la inauguración».\n13:00 · Horarios de shows y concurso únicamente si ya se confirmaron.\n18:30 · Dirección + horario de tienda 9–20 + recordatorio de promoción con condiciones.", "outline": ["10:30 · «Mañana empieza la inauguración».", "13:00 · Horarios de shows y concurso únicamente si ya se confirmaron.", "18:30 · Dirección + horario de tienda 9–20 + recordatorio de promoción con condiciones."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al plan de 5 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra. Usar recursos de los rodajes 5/11 y 19/11 (segundo propuesto). La actualidad del evento solo se muestra si tienda aporta material espontáneo real; no se programa un rodaje adicional.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1113' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P06", "date": "2026-11-14", "time": "08:30", "end_date": "2026-11-14", "kind": "post", "season": "niquia", "title": "Hoy comienza nuestra gran inauguración", "objective": "Activar la visita durante el primer día.", "caption": "¡Hoy empieza la celebración en Importados Niquía! 💛🖤 Este 14 y 15 de noviembre te esperamos en Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nVen a conocer la tienda, disfrutar el ambiente y descubrir el 20 % de descuento en gran parte de la tienda. Consulta las condiciones de la promoción en sede.\nHorario de tienda: 9:00 a. m. a 8:00 p. m. La programación de actividades se anunciará en nuestras stories. ¡Te esperamos!", "outline": ["Portada: «¡Es hoy! · Inauguración Niquía».", "Foto actual de tienda/equipo: abrir invitación.", "Descuento con exclusiones y vigencia aprobadas.", "Dirección, horario de tienda y programación aprobada si está lista."], "assets": [], "checks": ["Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Pieza producida con banco del rodaje 1; horario de tienda distinto de shows. Si el personal comparte fotos espontáneas del 14, guardarlas para P07/P08. No se programa un tercer rodaje ni se necesita material futuro para este anuncio.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P06' and plan_id='noviembre-2026';
