 update public.marketing_calendar_items set data='{"id": "P07", "date": "2026-11-15", "time": "09:00", "end_date": "2026-11-15", "kind": "post", "season": "niquia", "title": "Segundo día: nos vemos en Niquía", "objective": "Mantener asistencia con prueba real del primer día.", "caption": "¡La celebración sigue hoy en Niquía! 💛 Gracias a quienes nos acompañaron ayer. Este 15 de noviembre seguimos de inauguración en Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nAcércate, conoce la variedad y aprovecha el 20 % de descuento en gran parte de la tienda, según condiciones de la promoción.\nMira nuestras stories para consultar la programación confirmada de hoy. 🖤", "outline": ["Portada: «Hoy seguimos de inauguración».", "Foto real del 14/11 con público autorizado.", "Programa del día 15 solo con horarios confirmados; si falta, usar foto de productos.", "Dirección y condiciones del descuento."], "assets": [], "checks": ["Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración.", "Confirmar permiso de las personas reconocibles; no mostrar menores sin autorización de su responsable.", "Si no hay fotografías del 14/11, usar variante con fotos del rodaje 1 identificadas como tienda; no aparentar cobertura."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Usar fotos espontáneas del día 14 si las comparte la tienda. Si no hay material autorizado, sustituir las láminas de recuerdo por fotos del banco del 5/11 y texto de invitación; no presentarlas como cobertura del evento.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P07' and plan_id='noviembre-2026';
