 update public.marketing_calendar_items set data='{"id": "S1116", "date": "2026-11-16", "time": "10:30", "end_date": "2026-11-16", "kind": "story", "season": "navidad", "title": "Stories: ideas con decoración plateada", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · Video propio de decoración plateada; mostrar uso o detalle real, sin afirmar funciones no probadas.\n13:00 · Encuesta o caja: «¿Dónde lo pondrías o a quién se lo regalarías?»\n18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias.", "outline": ["10:30 · Video propio de decoración plateada; mostrar uso o detalle real, sin afirmar funciones no probadas.", "13:00 · Encuesta o caja: «¿Dónde lo pondrías o a quién se lo regalarías?»", "18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al plan de 5 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra. Usar recursos de los rodajes 5/11 y 19/11 (segundo propuesto). La actualidad del evento solo se muestra si tienda aporta material espontáneo real; no se programa un rodaje adicional.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1116' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1117", "date": "2026-11-17", "time": "10:30", "end_date": "2026-11-17", "kind": "story", "season": "navidad", "title": "Gracias, Niquía", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · Foto real del evento.\n13:00 · Recompartir P08.\n18:30 · Encuesta: «¿Viniste o nos visitas pronto?»", "outline": ["10:30 · Foto real del evento.", "13:00 · Recompartir P08.", "18:30 · Encuesta: «¿Viniste o nos visitas pronto?»"], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al plan de 5 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra. Usar recursos de los rodajes 5/11 y 19/11 (segundo propuesto). La actualidad del evento solo se muestra si tienda aporta material espontáneo real; no se programa un rodaje adicional.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1117' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P08", "date": "2026-11-17", "time": "18:30", "end_date": "2026-11-17", "kind": "post", "season": "comunidad", "title": "Gracias por una inauguración para recordar", "objective": "Conservar confianza y convertir asistentes en comunidad.", "caption": "¡Gracias por celebrar con nosotros, Niquía! 💛🖤 Nos quedamos con las sonrisas, la música y cada persona que pasó a conocernos este 14 y 15 de noviembre.\nDesliza para revivir algunos momentos. Si estuviste, cuéntanos qué fue lo que más disfrutaste. Seguimos aquí para acompañarte con variedad y nuevas ideas para tu hogar.\n#TiendasImportados #Niquía #Bello", "outline": ["Portada: foto propia de mayor emoción + «Gracias, Niquía».", "Ambiente y equipo.", "Trovadores y presentación artística realmente realizada.", "Actividad del concurso solo si fue realizada y se autorizan imágenes.", "Cierre: foto de fachada + «Nos seguimos encontrando aquí»."], "assets": [], "checks": ["Confirmar permiso de las personas reconocibles; no mostrar menores sin autorización de su responsable.", "Verificar qué actividades sí ocurrieron; no anunciar ganadores sin resultado y autorización confirmados."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Usar material espontáneo autorizado que comparta la tienda. Si no lo hay, producir agradecimiento gráfico con fotos de fachada/equipo del rodaje 1 y adaptar caption/láminas sin aparentar recap del evento. No se añade jornada profesional para cobertura ni se inventan resultados/ganadores.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P08' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1118", "date": "2026-11-18", "time": "10:30", "end_date": "2026-11-18", "kind": "story", "season": "navidad", "title": "Stories: inspiración de rincón navideño", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · Foto del banco existente: árbol y figura navideña.\n13:00 · Encuesta: «¿Dorado o plateado para tu rincón?»\n18:30 · Pregunta qué referencia buscan y consulta disponibilidad por sede.", "outline": ["10:30 · Foto del banco existente: árbol y figura navideña.", "13:00 · Encuesta: «¿Dorado o plateado para tu rincón?»", "18:30 · Pregunta qué referencia buscan y consulta disponibilidad por sede."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al plan de 5 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra. Usar recursos de los rodajes 5/11 y 19/11 (segundo propuesto). La actualidad del evento solo se muestra si tienda aporta material espontáneo real; no se programa un rodaje adicional.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1118' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "A02", "date": "2026-11-19", "time": "09:00", "end_date": "2026-11-19", "kind": "activity", "season": "niquia", "title": "Rodaje 2 · Navidad + Black Friday", "objective": "Grabar R03 y R04 y completar el banco fotográfico para los 15 posts y las stories de cierre de mes.", "caption": "", "outline": ["Fecha propuesta: jueves 19 de noviembre, 09:00–14:00; por confirmar con Samuel y la tienda. Es la segunda y última jornada de producción.", "09:00–09:30 · Revisar existencias/referencias, condiciones de Black Friday, espacios y permisos. No fijar precios sin validación.", "09:30–10:45 · R03: antes/después del rincón navideño, con encuadre fijo y detalles. Sacar fotos de cada paso para P09.", "10:45–12:00 · R04: lista navideña y Black Friday; filmar árbol, figura, tren, decoración y hogar con planos modulares.", "12:00–13:00 · Fotografías para P10–P15: dorado/plateado, selección de regalos y hogar; banco de stories hasta el 6/12.", "13:00–14:00 · Recursos de producto, interacción, fachadas y locuciones alternativas. Capturar versión sin descuento para diciembre.", "Entrega: P09 queda listo para el 19 a las 18:30 usando fotos existentes si no alcanza la selección; R03 el 20 a las 18:30; R04 edición 20–23, revisión 24 y cierre 25 para publicar el 26."], "assets": [], "checks": ["Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración.", "Confirmar día y hora de cada artista y actividad; presentar a la artista como imitadora de Arelys Henao de Yo Me Llamo, sin sugerir que viene la cantante original."], "script": [], "format": "Rodaje 2 de 2 · jueves 19 propuesto", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Segunda fecha propuesta, aún no confirmada. Toda la captura profesional se concentra en las dos jornadas. La cobertura espontánea de tienda durante actividades no es un tercer rodaje contr