 update public.marketing_calendar_items set data='{"id": "P14", "date": "2026-11-29", "time": "09:00", "end_date": "2026-11-29", "kind": "post", "season": "black-friday", "title": "Último día de Black Friday", "objective": "Recordar el cierre real de la promoción sin escasez inventada.", "caption": "¡Hoy, 29 de noviembre, es el último día de nuestro Black Friday! 🖤💛 Aprovecha el 20 % de descuento en toda la tienda, según condiciones de la promoción.\nTrae tu lista de Navidad o consulta por WhatsApp las referencias que te interesan. No dejes para después la visita que ya tenías en mente.\nEscríbenos al WhatsApp 312 706 2214 o visítanos en tienda.", "outline": ["Portada: «Último día · 29 noviembre».", "Dos o tres referencias con disponibilidad comprobada ese mismo día.", "Sedes y horario confirmado para domingo; no asumir horario especial.", "Cierre: «Hoy termina» + condiciones. No usar «últimas unidades» sin conteo real."], "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/06-decoracion-plateada.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación.", "Validar por escrito alcance del 20 % en toda la tienda, sedes, precio base, vigencia 27–29 noviembre y condiciones. No sumar ni prolongar descuentos de inauguración.", "Confirmar horario de domingo 29/11 y hora exacta de cierre de la promoción."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": " Banco del rodaje 2 del jueves 19/11 propuesto; se completan selección, edición y revisión antes de cada fecha, sin más jornadas. Los datos de precio/stock se revalidan antes de publicar.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P14' and plan_id='noviembre-2026';
