 update public.marketing_calendar_items set data='{"id": "S1205", "date": "2026-12-05", "time": "10:30", "end_date": "2026-12-05", "kind": "story", "season": "navidad", "title": "Stories: ideas con licuadora", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · Video propio de licuadora; mostrar uso o detalle real, sin afirmar funciones no probadas.\n13:00 · Encuesta o caja: «¿Dónde lo pondrías o a quién se lo regalarías?»\n18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias.", "outline": ["10:30 · Video propio de licuadora; mostrar uso o detalle real, sin afirmar funciones no probadas.", "13:00 · Encuesta o caja: «¿Dónde lo pondrías o a quién se lo regalarías?»", "18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al plan de 5 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra. Usar recursos de los rodajes 5/11 y 19/11 (segundo propuesto). La actualidad del evento solo se muestra si tienda aporta material espontáneo real; no se programa un rodaje adicional.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1205' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1206", "date": "2026-12-06", "time": "10:30", "end_date": "2026-12-06", "kind": "story", "season": "navidad", "title": "Stories: ideas con olla arrocera", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · Video propio de olla arrocera; mostrar uso o detalle real, sin afirmar funciones no probadas.\n13:00 · Encuesta o caja: «¿Dónde lo pondrías o a quién se lo regalarías?»\n18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias.", "outline": ["10:30 · Video propio de olla arrocera; mostrar uso o detalle real, sin afirmar funciones no probadas.", "13:00 · Encuesta o caja: «¿Dónde lo pondrías o a quién se lo regalarías?»", "18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al plan de 5 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra. Usar recursos de los rodajes 5/11 y 19/11 (segundo propuesto). La actualidad del evento solo se muestra si tienda aporta material espontáneo real; no se programa un rodaje adicional.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1206' and plan_id='noviembre-2026';
 delete from public.marketing_calendar_items where id in ('A03','A04') and plan_id='noviembre-2026';
 insert into public.marketing_calendar_items(id,plan_id,data) values('R05','noviembre-2026','{"id": "R05", "date": "2026-11-09", "time": "18:30", "end_date": "2026-11-09", "kind": "reel", "season": "niquia", "title": "Reel para pauta · la inauguración completa", "objective": "Convocar visitas a Niquía antes del 14/15 con todas las dinámicas en una sola pieza preparada para pauta, sin activar gasto desde el calendario.", "caption": "¡Niquía, el 14 y 15 de noviembre tenemos una gran celebración para ti! 💛🖤\n\n🎉 Gran inauguración de Importados Niquía.\n🏷️ 20 % de descuento en gran parte de la tienda.\n🏍️ Rifa de una moto AKT y patinetes eléctricos: compra en tienda y sigue a @tiendasimportados para participar, según bases completas de la actividad.\n🎤 Toto y Sirirí, música en vivo y la imitadora de Arelys Henao de Yo Me Llamo.\n🏆 Concurso «Culi chupado»: premio de $500.000 en efectivo + $500.000 para gastar en la tienda.\n\n📍 Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nGuarda las fechas y ven con quien quieras compartir este plan. Consulta programación, requisitos, exclusiones y bases completas antes de participar.\n\n#TiendasImportados #Niquía #Bello #Inauguración", "outline": ["Reel adicional: total del plan 5 reels y 15 posts. Publicación orgánica propuesta lunes 9/11 a las 18:30, cinco días antes del primer día de celebración.", "Un solo reel maestro vertical de 50–55 s, con módulos grabados en rodaje 1 del jueves 5. Inicio: fachada/presentador y fecha; cierre: dirección y llamada a visitar.", "Incluye todas las dinámicas confirmadas: 20 % en casi toda la tienda; moto AKT y patinetes; compra + seguir Instagram; Toto y Sirirí; música en vivo; imitadora de Arelys Henao de Yo Me Llamo; concurso y sus dos premios de $500.000.", "No inventar horario de show, sorteo o concurso. No asignar artistas a ambos días sin confirmación. Horario de tienda no es programación de actividades.", "Exportar maestro sin marcas de agua, audio con uso comercial autorizado y subtítulos. Revisar zonas de interfaz en la vista previa de cada ubicación de Meta; mantener fechas, premios y condiciones legibles.", "Entregables de pauta de la misma pieza: video maestro, portada, caption principal, título «14 y 15 · Inauguración en Niquía» y texto corto «Ven a celebrar en Importados · edificio Valkiria». No son reels adicionales.", "Activación de pauta propuesta 9–13/11 para convocar antes del evento; continuidad 14/15 solo con anuncio actualizado y vigencia aprobada. Presupuesto, destino/objetivo y campaña requieren configuración y autorización aparte; publicar el reel no enciende un anuncio.", "Si al 8/11 faltan bases o autorizaciones, conservar R05 en revisión, no pautarlo incompleto. Revalidar fecha del 9 o usar una invitación sin premios; no afirmar que incluye todas las dinámicas si se omiten."], "assets": [], "checks": ["Aprobar bases de la rifa: compra mínima si aplica, fechas, comprobante, número de participaciones, requisitos, fecha/método del sorteo, entrega, modelos/cantidades de premios y revisión de requisitos aplicables. Compra + seguir Instagram es la única mecánica confirmada.", "Aprobar bases, edades, dinámica y seguridad del concurso «Culi chupado», cupos y entrega de premios: $500.000 en efectivo + $500.000 para gastar en tienda. No prometer $1.000.000 en efectivo.", "Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración.", "Confirmar día y hora de cada artista y actividad; presentar a la artista como imitadora de Arelys Henao de Yo Me Llamo, sin sugerir que viene la cantante original.", "Autorización del material promocional de artistas.", "Aprobar bases accesibles de rifa y concurso, exclusiones del descuento y referencias reales de los premios antes de publicar o pautar; no basta una frase genérica «aplican condiciones».", "Revisar requisitos de Meta para la promoción concreta y elegibilidad del anuncio con premios antes de activar pauta; no se asume aprobación ni permiso.", "Confirmar presupuesto, duración, zona geográfica, objetivo y destino del anuncio, y revisar el montaje final con los dueños. No hay inversión automática."], "script": [{"time": "0–3 s", "visual": "Presentador frente a la fachada, plano cercano y fecha grande.", "voice": "¡Niquía! Guarda el 14 y 15 de noviembre: tenemos un plan para ti.", "text": "14 y 15 NOV · Inauguración Niquía"}, {"time": "3–8 s", "visual": "Recorrido breve de pasillo con productos reales.", "voice": "Celebramos la gran inauguración de Importados, con 20 % en gran parte de la tienda.", "text": "20 % en gran parte de la tienda · consulta exclusiones"}, {"time": "8–18 s", "visual": "Moto y patinetes reales o artes autorizados; señalar requisitos con rótulos claros.", "voice": "Habrá rifa de una moto AKT y patinetes eléctricos. Compra en tienda y síguenos en Instagram para participar, según las bases.", "text": "Rifa: moto AKT + patinetes · Compra + seguir @tiendasimportados · consulta bases completas"}, {"time": "18–29 s", "visual": "Presentador alterna con fotos/artes autorizados de artistas, sin grabaciones de shows futuros.", "voice": "Nos acompañan Toto y Sirirí, música en vivo y la imitadora de Arelys Henao de Yo Me Llamo.", "text": "Toto y Sirirí · Música en vivo · Imitadora de Arelys Henao / Yo Me Llamo"}, {"time": "29–41 s", "visual": "Presentador anuncia concurso; animación con dos bloques de premio separados.", "voice": "Y el concurso Culi chupado tendrá un premio de quinientos mil en efectivo y quinientos mil para gastar en la tienda.", "text": "Concurso «Culi chupado» · $500.000 efectivo + $500.000 en tienda · requisitos en bases"}, {"time": "41–49 s", "visual": "Fachada y dirección, encuadre estable, letra legible.", "voice": "Ven con tu parche a Valkiria, Diagonal 55 Av 38-33, Niquía.", "text": "Diagonal 55 Av 38-33 · Edificio Valkiria · Niquía"}, {"time": "49–55 s", "visual": "Presentador invita y tarjeta final; CTA de visita.", "voice": "Revisa las bases y la programación. ¡Te esperamos el 14 y 15 en Importados!", "text": "14 y 15 NOV · Guarda las fechas · Consulta bases y programación"}], "format": "Reel adicional para Meta Ads · 1080 × 1920 · 50–55 s", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Rodaje 1 · jueves 5/11, bloque 11:00–12:15. Grabar presentador, fachada y módulos de cada dinámica; planos reales de premios si están disponibles, artes autorizados en caso contrario. Montaje 6/11, revisión 7/11, aprobación y condiciones cerradas 8/11, publicación propuesta 9/11 a las 18:30. El 9/11 es entrega/publicación, no una tercera jornada. R05 concentra la pauta de inauguración; R02 se mantiene orgánico.", "revision": 1}'::jsonb);
 update public.marketing_calendar_plans set meta='{"title": "Calendario comercial · noviembre 2026", "edition": "2026-11-03", "timezone": "America/Bogota", "start": "2026-11-01", "end": "2026-12-06", "scope": "5 reels (4 orgánicos + 1 adicional para pauta Meta) + 15 posts de feed. Solo 2 rodajes: jueves 5/11 confirmado y jueves 19/11 propuesto. 34 secuencias de stories hasta el 6/12, adicionales al feed. Horarios propuestos; el calendario no publica ni activa pauta.", "strategy": [{"title": "Cinco reels, funciones distintas", "body": "R01: recorrido POV local. R02: invitación orgánica breve de tres motivos. R03: antes/después navideño. R04: lista navideña/Black Friday. R05: anuncio adicional de inauguración con todas las dinámicas, pensado para Meta Ads y publicado el 9/11 antes del evento. Son hipótesis creativas para la tienda, sin promesa de viralidad."}, {"title": "Una campaña que acumula intención", "body": "Natillada y ubicación generan confianza; invitación y cobertura llevan a la inauguración; memoria del evento valida la experiencia; guías y lista preparan Black Friday; diciembre vuelve a inspiración sin prolongar el 20 %."}, {"title": "Grabación que se puede ejecutar", "body": "Solo dos rodajes profesionales. Jueves 5/11 confirmado: R01, R02, R05 y banco fotográfico/recursos de inauguración y primera selección navideña. Jueves 19/11 propuesto: R03, R04 y banco de Navidad/Black Friday para el cierre. Horario sugerido 09:00–14:00 ambos días. El resto es edición, diseño y programación; no hay rodajes el 4, 9, 16 o 23. Para memorias de eventos, usar material existente/espontáneo compartido por tienda o agradecimientos gráficos; no fingir cobertura. Video propio vertical, voz, subtítulos y música apta para uso comercial."}, {"title": "Horario de partida, no «mejor hora» probada", "body": "Feed entre semana 18:30; sábado de lista/selección 11:30; anuncios de inicio 08:30/09:00. Stories en tres ventanas, con cobertura extra en eventos. America/Bogota. Ajustar con Insights propios tras dos semanas: no tenemos métricas actuales de la cuenta. R03 pasa del 18 al 20/11 para editar después del segundo rodaje. R05 va el 9/11 a las 18:30. El 5/11 R01 tiene edición prioritaria para las 18:30; si no se aprueba a tiempo, reprogramar explícitamente."}, {"title": "Medición útil para retail", "body": "A las 24 h y 7 días: alcance, tiempo medio de reproducción y retención si están disponibles, compartidos/alcance, guardados/alcance, visitas al perfil y seguidores netos. Registrar consultas cualificadas por pieza (producto + sede + intención), visitas autodeclaradas y ventas verificadas por separado. No confundir reproducción, clic o consulta con venta."}, {"title": "Pauta después de validar la pieza", "body": "R05 es la pieza adicional dedicada a convocatoria de inauguración: publicar el 9/11, con rodaje el 5, edición 6, revisión 7 y cierre de condiciones/aprobación 8. Propuesta de pauta 9–13/11, sin gasto ni activación desde el módulo. R02 queda orgánico para no duplicar inversión. R04 puede apoyar Black Friday si se autoriza otra campaña. Definir presupuesto, objetivo, destino y área de captación real de Niquía; comprobar bases y elegibilidad del anuncio antes de pautar premios. Medir consultas/visitas y ventas verificadas por separado, sin prometer resultados."}, {"title": "Productos reales, no catálogo cerrado", "body": "Las ocho fotos aportadas son referencias de licuadora, arrocera, trenes, Papá Noel, detalles dorados/plateados y árboles. Las etiquetas fotografiadas no son autorización para anunciar precios ni aplicarles otro descuento. Solicitar un inventario visual adicional de Navidad; mostrar luces, bolas, guirnaldas o empaques solo si se confirma que se venden."}, {"title": "Revisión de Instagram: alcance y límite", "body": "Se intentó revisar el perfil público y su embed el 3/11/2026: Instagram bloqueó la lectura automatizada y la búsqueda no recuperó publicaciones verificables. No se atribuyen métricas, frecuencia ni piezas recientes a la cuenta. El material previamente compartido muestra fachada, presentadora y estética amarilla/negra; se mantiene esa continuidad. Antes de producir, el equipo debe contrastar los 19 temas con el feed real y evitar duplicados."}, {"title": "Promociones con información clara", "body": "Inauguración: 20 % en casi toda la tienda, sin transformarlo en «toda». Black Friday: 20 % en toda la tienda 27–29, pendiente de condiciones finales. Rifa: compra y seguir Instagram confirmados; faltan bases. Concurso: dos componentes de $500.000, sin sumar como efectivo. Artista: imitadora de Arelys Henao, sin aparentar contratación de la cantante original. Horarios de shows sin definir."}], "sources": [{"title": "Meta · Best Practices de Instagram", "url": "https://about.fb.com/news/2024/10/best-practices-education-hub-creators-instagram/", "finding": "Meta organiza recomendaciones de creación, interacción y alcance y ofrece consejos personalizados en el panel profesional. Sustenta revisar Insights propios, sin afirmar una hora universal."}, {"title": "Meta · Trial Reels", "url": "https://about.fb.com/news/2024/12/trial-reels-try-content-non-followers-first-see-what-perfoms-best/", "finding": "Meta describe pruebas con no seguidores para explorar formatos. Si la función aparece en la cuenta, usarla en R01 o R03; mantener R02 y R04 en el calendario normal por su vigencia. El plan ahora incluye el quinto reel de pauta autorizado por Samuel; las tomas alternativas no añaden más reels."}, {"title": "Meta · Creatividad y pruebas", "url": "https://about.fb.com/news/2025/06/inspiring-creativity-that-brings-people-together/", "finding": "Apoya experimentar con contenido y observar la respuesta. Los formatos y guiones propuestos aquí son una inferencia creativa para Importados, no un estudio de ventas de esta cuenta."}, {"title": "Instagram de Importados · revisión manual pendiente", "url": "https://www.instagram.com/tiendasimportados/", "finding": "Fuente propia a contrastar por el equipo; no se pudo auditar el feed actual desde esta sesión."}], "production_revision": "two-shoots-v2"}'::jsonb where id='noviembre-2026';
end $calendar$;
commit;
